  id: number;
  title: string;
  content: string;
  app_context: string;
  publish_date: string;
  priority: 'low' | 'medium' | 'high';
}

export interface SubApp {
  id: string;
  name: string;
  description: string;
  icon_type: string;
  color_theme: string;
  route_path: string;
  is_active: boolean;
}

export interface ScanResult {
  id: string;
  instanceId: string;
  database: string;
  table: string;
  column: string;
  ruleName: string;
  riskLevel: 'high' | 'medium' | 'low';
  timestamp: string;
}

export interface InspectionRecord {
  id: string;
  timestamp: string;
  type: 'backup' | 'replication' | 'ha' | 'vip';
  status: 'success' | 'warning' | 'error';
  details: string;
  instanceId: string;
}

